using System.Diagnostics;using System.Text.Json;using CUE4Parse.FileProvider;using CUE4Parse.UE4.Assets.Exports.StaticMesh;using CUE4Parse_Conversion;using CUE4Parse_Conversion.Meshes;
public static class MeshCheck {public static void Run(DefaultFileProvider provider,string source,string root){Directory.CreateDirectory(root);var mesh=provider.LoadPackage(source.Split('.')[0]).GetExports().OfType<UStaticMesh>().First();var options=new ExporterOptions{MeshFormat=EMeshFormat.Gltf2,ExportMaterials=false,LodFormat=ELodFormat.FirstLod};var t=Stopwatch.StartNew();var direct=new DirectMesh(mesh,options);var directSeconds=t.Elapsed.TotalSeconds;File.WriteAllBytes(Path.Combine(root,mesh.Name+"-direct.glb"),direct.MeshLods[0].FileData);t.Restart();var reference=new MeshExporter(mesh,options);var referenceSeconds=t.Elapsed.TotalSeconds;File.WriteAllBytes(Path.Combine(root,mesh.Name+"-reference.glb"),reference.MeshLods[0].FileData);Console.WriteLine(JsonSerializer.Serialize(new{source,directSeconds,referenceSeconds,directBytes=direct.MeshLods[0].FileData.Length,referenceBytes=reference.MeshLods[0].FileData.Length}));}}
